import os, yaml
from collections import Counter

tags = Counter()
types = Counter()

for root, dirs, files in os.walk('Agents'):
    for f in files:
        if not f.endswith('.md') or f.startswith('_'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            text = fh.read()
        if not text.startswith('---'):
            continue
        end = text.find('---', 3)
        if end == -1:
            continue
        try:
            fm = yaml.safe_load(text[3:end]) or {}
        except:
            continue
        for t in fm.get('tags', []):
            if isinstance(t, str):
                tags[t] += 1
        atype = fm.get('type', 'unknown')
        types[atype] += 1

print('Top tags:')
for tag, count in tags.most_common(20):
    print(f'  {tag}: {count}')
print(f'\\nArtifact types:')
for t, count in types.most_common():
    print(f'  {t}: {count}')
" 2>&1

