import os, re, yaml
from collections import Counter

# Concepts too generic to auto-link (would create noise)
EXCLUDE = {
    'concept', 'alignment', 'optimizations', 'frameworks', 'benchmarking',
    'data-analysis', 'deployment', 'self-improvement', 'debugging',
    'resilience', 'scalability', 'sustainability', 'visualization',
    'simulation', 'architecture', 'testing', 'automation', 'integration',
    'monitoring', 'security', 'performance', 'documentation',
}

# Build concept dictionary
concept_notes = {}
for d in ['cortex', 'sensory', 'cerebellum', 'prefrontal', 'memory', 'motor', 'genome', 'laboratory']:
    if not os.path.isdir(d):
        continue
    for f in os.listdir(d):
        if not f.endswith('.md') or f.startswith('_'):
            continue
        stem = f[:-3]
        if stem.startswith('MOC-') or stem == '_index':
            continue
        if stem.lower() in EXCLUDE:
            continue
        concept_notes[stem.lower()] = stem

# Build patterns (only 4+ char concepts)
patterns = {}
for lower_stem, stem in concept_notes.items():
    if len(stem) < 4:
        continue
    words = stem.split('-')
    if len(words) == 1:
        pat = r'\b' + re.escape(stem) + r'\b'
    else:
        pat = r'\b' + r'[\s-]'.join(re.escape(w) for w in words) + r'\b'
    patterns[lower_stem] = (re.compile(pat, re.IGNORECASE), stem)

# Scan Agents/
link_pat = re.compile(r'\[\[([^\]|#]+)')
files_to_update = {}
total_new_links = 0

for root, dirs, files in os.walk('Agents'):
    for f in files:
        if not f.endswith('.md') or f.startswith('_'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            text = fh.read()
        existing = set(t.strip().lower() for t in link_pat.findall(text))
        body = text
        if text.startswith('---'):
            end = text.find('---', 3)
            if end != -1:
                body = text[end+3:]

        new_links = set()
        for lower_stem, (pat, stem) in patterns.items():
            if lower_stem in existing:
                continue
            if pat.search(body):
                new_links.add(stem)

        if new_links:
            files_to_update[path] = new_links
            total_new_links += len(new_links)

concept_counts = Counter()
for links in files_to_update.values():
    for l in links:
        concept_counts[l] += 1

print(f'Files to update: {len(files_to_update)} / 427')
print(f'Total new links: {total_new_links}')
print(f'Avg new links per file: {total_new_links / max(len(files_to_update),1):.1f}')
print(f'\\nTop matched concepts (filtered):')
for concept, count in concept_counts.most_common(20):
    print(f'  [[{concept}]]: {count} files')
" 2>&1

